<script setup lang="ts">import {computed,ref} from 'vue';import AppShell from '@/components/zs/AppShell.vue';import PageHeader from '@/components/zs/PageHeader.vue';import Panel from '@/components/zs/Panel.vue';import IntegrationCard from '@/components/crm/IntegrationCard.vue';import {useCrmData} from '@/composables/useCrmData';import type {EmailIntegration} from '@/types/crm';import {setPageMeta} from '@/lib/page-meta';setPageMeta('Email Integrations','Prepare Gmail and Outlook connections for outreach.');const d=useCrmData(),states=ref<Record<string,EmailIntegration['status']>>({});const rows=computed(()=>(d.integrations.data.value??[{id:'gmail',companyId:d.activeCompanyId.value,provider:'Gmail' as const,email:'',status:'Not Connected' as const},{id:'outlook',companyId:d.activeCompanyId.value,provider:'Microsoft Outlook' as const,email:'',status:'Not Connected' as const}]).map(x=>({...x,status:states.value[x.id]??x.status})));function connect(x:EmailIntegration){states.value[x.id]='Connecting';setTimeout(()=>states.value[x.id]='Connected',800)}</script>
<template><AppShell><PageHeader title="Email Integrations" description="Connect sender identities for outreach; OAuth and sending are not enabled in this preview"/><Panel title="Providers" description="Connection status is simulated locally" body-class="grid gap-3 p-4 md:grid-cols-2"><IntegrationCard v-for="x in rows" :key="x.id" :integration="x" @connect="connect(x)" @disconnect="states[x.id]='Not Connected'"/></Panel></AppShell></template>
